"""tr — sira_c."""

T = {
"sira_151": ("Peygamberin ﷺ hangi amcası Müslüman oldu ve Mekke'de onun en güçlü savunucularından biri oldu?", ["Hamza b. Abdülmuttalib", "Ebu Leheb", "Ebu Talib", "Abbas"], "Peygamberin ﷺ amcası ve süt kardeşi olan Hamza Mekke'de Müslüman oldu ve «Allah'ın aslanı» diye anıldı."),
"sira_152": ("İlk Müslümanlar Mekke'de kimin evinde gizlice toplanıyordu?", ["Erkam'ın evinde", "Ebu Bekir'in evinde", "Hatice'nin evinde", "Ebu Talib'in evinde"], "Safa tepesindeki Erkam b. Ebi'l-Erkam'ın evi ilk toplanma ve öğretim yeri oldu."),
"sira_153": ("Mekke'de Müslüman olan hangi sahabi daha sonra Yesrib'e ilk öğretmen olarak gönderildi?", ["Mus'ab b. Umeyr", "Bilal b. Rebah", "Halid b. Velid", "Ebu Hureyre"], "Soylu bir aileden genç bir Mekkeli olan Mus'ab b. Umeyr, Akabe biatından sonra Kur'an öğretmek üzere Yesrib'e gönderildi."),
"sira_154": ("Açık davetin başladığı Müddessir suresi hangi emirle başlar?", ["«Ey örtüsüne bürünen! Kalk ve uyar»", "«Rabbinin adıyla oku»", "«Kâfirlerle savaş»", "«Medine'ye hicret et»"], "«Ey örtüsüne bürünen! Kalk ve uyar»."),
"sira_155": ("Hangi ayet Peygambere ﷺ emrolunduğu şeyi açıkça bildirmesini emretti?", ["«Sana emrolunanı açıkça bildir»", "«Sabret»", "«Gizlice oku»", "«Çekil»"], "«Sana emrolunanı açıkça bildir ve müşriklerden yüz çevir»."),
"sira_156": ("Kureyş, Haşimoğullarına karşı boykot belgesini nereye astı?", ["Kâbe'nin içine", "Şehir kapısına", "Ukaz panayırına", "Safa tepesine"], "Boykot metni Kâbe'nin içine asıldı; sonunda anlaşma bozuldu ve belge terk edildi."),
"sira_157": ("Taif'te kovulduktan sonra Peygamber ﷺ kimin bağına sığındı ve bir salkım üzüm ikram edildi?", ["Utbe ve Şeybe'nin bağına; köle Addas ona hizmet etti", "Taif reisinin evine", "Geçen bir kervana", "Bir demircinin evine"], "Yaralanıp Taif'ten çıkarılınca bir bağa sığındı; orada Addas adlı Hristiyan bir köle eliyle kendisine üzüm sunuldu."),
"sira_158": ("Önce şiddetli bir düşman olan hangi sahabi Müslüman oldu ve «hakkı batıldan ayıran» diye anıldı?", ["Ömer b. Hattab", "Ebu Süfyan", "Halid b. Velid", "Amr b. As"], "Başlangıçta düşman olan Ömer b. Hattab Mekke'de Müslüman oldu ve Faruk unvanını aldı."),
"sira_159": ("Peygamber ﷺ Medine'ye varınca devesinin çöktüğü yerde hangi ailenin evinde kaldı?", ["Ebu Eyyub el-Ensari'nin evinde", "Sa'd b. Muaz'ın evinde", "Ubey b. Ka'b'ın evinde", "Enes b. Malik'in evinde"], "Deve Ebu Eyyub el-Ensari'nin evi yanında çöktü; o da gelişinde Peygamberi ﷺ misafir etti."),
"sira_160": ("Birçok sahabinin defnedildiği Medine mezarlığının adı nedir?", ["Baki", "Mualla", "Hicr", "Kuba"], "Peygamber ﷺ Mescidi'nin yanındaki Baki el-Garkad Medine'nin mezarlığıdır."),
"sira_161": ("Kur'an hangi mescit için «ilk günden takva üzerine kurulmuştur» der?", ["Kuba Mescidi", "Mescid-i Haram", "Mescid-i Aksa", "Kûfe Mescidi"], "«İlk günden takva üzerine kurulan mescit, içinde namaz kılmana elbette daha lâyıktır»."),
"sira_162": ("Kıble değiştirme emri indiğinde Peygamber ﷺ hangi mescitte namaz kılıyordu?", ["İki kıbleli mescit (Mescid-i Kıbleteyn)", "Kuba Mescidi", "Mescid-i Haram", "Mescid-i Aksa"], "Emir namaz sırasında geldi; cemaat Kâbe'ye yöneldi, bu yüzden «iki kıbleli mescit» adını aldı."),
"sira_163": ("Hicretin ikinci yılında Müslümanlara hangi ibadet farz kılındı?", ["Ramazan orucu", "Hac", "Gece namazı", "Taif yolculuğu"], "Ramazan orucu hicretin ikinci yılında Medine'de farz kılındı."),
"sira_164": ("Hangi sahabi ezan sözlerini rüyada gördü ve Peygamber ﷺ bunu benimsedi?", ["Abdullah b. Zeyd", "Bilal b. Rebah", "Ebu Bekir", "Muaz b. Cebel"], "Abdullah b. Zeyd ezan rüyasını anlattı; Peygamber ﷺ onu onayladı ve Bilal'e okumasını emretti."),
"sira_165": ("Kur'an, Peygamberin ﷺ Bedir'de attığı bir avuç toprak hakkında ne der?", ["«Attığın zaman sen atmadın, Allah attı»", "«İyi nişan aldın»", "«Rüzgâr taşıdı»", "«Melekler attı»"], "«Attığın zaman da sen atmadın, fakat Allah attı»."),
"sira_166": ("Kur'an bazı müminlerin Bedir'e çıkarkenki halini nasıl anlatır?", ["Ölüme sürükleniyorlarmış gibi bu konuda tartışıyorlardı", "Hepsi istekliydi", "Çıkmayı reddettiler", "Erteleme istediler"], "«Hak ortaya çıktıktan sonra sanki göz göre göre ölüme sürükleniyorlarmış gibi seninle tartışıyorlardı»."),
"sira_167": ("Kur'an müminlere zaferden önceki durumlarını nasıl hatırlatır?", ["Yeryüzünde az ve zayıf düşürülmüş idiler; sonra Allah onları barındırdı ve yardımıyla destekledi", "Zengindiler", "Kalabalıktılar", "Zaten hükmediyorlardı"], "«Hatırlayın ki bir zaman siz yeryüzünde az ve zayıf düşürülmüş idiniz… O sizi barındırdı ve yardımıyla destekledi»."),
"sira_168": ("Bedir'de hangi sahabi orduyu düşmana en yakın kuyuya taşımayı önerdi?", ["Hubab b. Münzir", "Sa'd b. Muaz", "Mikdad", "Zübeyr"], "Hubab b. Münzir bu yerin vahiy mi yoksa görüş mü olduğunu sordu; görüş olduğunu öğrenince kuyuya ilerlemeyi önerdi ve Peygamber ﷺ kabul etti."),
"sira_169": ("Bedir savaşının yanında gerçekleştiği su kaynağının adı neydi?", ["Bedir, kervan yolu üzerinde bir su", "Zemzem", "Kuba", "Hudeybiye"], "Bedir, Mekke ile Şam arasındaki kervan yolu üzerinde bir suydu; savaş adını ondan aldı."),
"sira_170": ("Bedir'den sonra esirlerle ilgili hangi mesele vahiyle ele alındı?", ["Esirler için kabul edilen fidye", "Suyun paylaşımı", "Konak yerinin seçimi", "Dönüş tarihi"], "İlgili bölüm esirlerden ve fidyeden söz eder, ardından alınanı helâl ve temiz kılar."),
"sira_171": ("Âl-i İmran suresine göre Uhud'da ilk başarıdan sonra durumu ne değiştirdi?", ["Verilen emir hakkında tartışma ve isyan", "Düşmanın sayısı", "Sıcak", "Su kıtlığı"], "«…nihayet gevşediniz, emir hakkında tartıştınız ve isyan ettiniz»."),
"sira_172": ("Kur'an, Allah yolunda öldürülenler hakkında ne der?", ["Onları ölü sanma: Rableri katında diridirler", "Kıyamete kadar uyurlar", "Geri dönerler", "Unutulurlar"], "«Allah yolunda öldürülenleri sakın ölü sanma: bilakis onlar diridir, Rableri katında rızıklandırılmaktadırlar»."),
"sira_173": ("Peygamber ﷺ Uhud'da okçuları hangi tepeye yerleştirdi?", ["Okçular tepesine (Cebelü'r-Rumat)", "Safa tepesine", "Sevr dağına", "Hira dağına"], "Elli okçu, sonradan «okçular tepesi» diye anılan bir tepeye yerleştirildi ve oradan ayrılmamaları emredildi."),
"sira_174": ("Ahzab suresi Medine kuşatmasının şiddetini nasıl anlatır?", ["Gözler kaydı ve yürekler ağızlara geldi", "Şehir düştü", "Sadece yiyecek tükendi", "Gökyüzü karardı"], "«Hani onlar üstünüzden ve altınızdan gelmişlerdi; gözler kaymış, yürekler ağızlara gelmişti»."),
"sira_175": ("Kur'an Hendek savaşının sonucunu nasıl anlatır?", ["Allah kâfirleri hiçbir hayra ulaşmadan öfkeleriyle geri çevirdi", "Uzun bir meydan savaşı", "Bir barış antlaşması", "Müslümanların geri çekilmesi"], "«Allah kâfirleri hiçbir hayra ulaşmadan öfkeleriyle geri çevirdi; savaşta Allah müminlere yetti»."),
"sira_176": ("Meşhur antlaşmanın yapıldığı Hudeybiye nerededir?", ["Mekke'nin batısında, harem sınırında", "Medine yakınında", "Yemen'de", "Şam'da"], "Hudeybiye, Mekke haremi sınırında bir yerdir; antlaşma orada yapıldı."),
"sira_177": ("Hudeybiye'den sonra Kur'an Peygamberin ﷺ hangi rüyasını doğrular?", ["Mescid-i Haram'a güven içinde, saçları tıraşlı veya kısaltılmış olarak gireceklerini", "Hayber'de galip geleceklerini", "Bir şehir kuracaklarını", "Şam'a yolculuk edeceklerini"], "«Andolsun ki Allah, Elçisinin rüyasını doğru çıkardı: Mescid-i Haram'a güven içinde gireceksiniz»."),
"sira_178": ("Fetih suresi Mekke'de tutulan eller hakkında neyi hatırlatır?", ["Allah Mekke vadisinde onların ellerini sizden, sizin ellerinizi onlardan çekti", "Savaşı emretti", "Yolları kapattı", "Bir fırtına gönderdi"], "«Sizi onlara galip getirdikten sonra Mekke vadisinde onların ellerini sizden, sizin ellerinizi onlardan çeken O'dur»."),
"sira_179": ("Hayber seferi hicretin hangi yılında oldu?", ["Yedinci", "İkinci", "Beşinci", "Onuncu"], "Hayber, Hudeybiye antlaşmasının ertesi yılı olan hicretin 7. yılında gerçekleşti."),
"sira_180": ("Hudeybiye'den bir yıl sonra antlaşma gereği yapılan umreye ne denir?", ["Umretü'l-kaza", "Veda haccı", "Ci'râne umresi", "Hacc-ı ekber"], "Antlaşma Müslümanların ertesi yıl dönmelerini öngörüyordu; bu umreye umretü'l-kaza denir."),
"sira_181": ("Hangi hükümdar Peygamberin ﷺ mektubunu yırttı?", ["İran kralı (Kisra)", "Habeş Necaşisi", "Bahreyn valisi", "Yemen kralı"], "Peygamber ﷺ komşu hükümdarlara mektuplar gönderdi; İran kralına gönderilen mektup yırtıldı."),
"sira_182": ("Peygamberin ﷺ mektubunu Habeş Necaşisine ve başka hükümdarlara hangi sahabi götürdü?", ["Amr b. Ümeyye ed-Damri", "Ebu Hureyre", "Enes b. Malik", "Ubey b. Ka'b"], "Elçiler sahabiler arasından seçildi; Necaşiye Amr b. Ümeyye ed-Damri gönderildi."),
"sira_183": ("Hayber, Medine'ye göre hangi yöndedir?", ["Kuzeyde", "Güneyde", "Doğuda", "Batıda, deniz kıyısında"], "Hayber, Medine'nin kuzeyinde, Şam yolu üzerinde müstahkem bir vahadır."),
"sira_184": ("Mekke'nin fethi günü Ebu Süfyan'ın evi ne oldu?", ["Girene güvenlik yeri", "Bir hapishane", "Bir depo", "Bir mescit"], "Peygamber ﷺ Mescid-i Haram'a giren, evinde kalan veya Ebu Süfyan'ın evine giren için güvenlik ilan etti."),
"sira_185": ("Hangi yıl «fetih yılı» ('âmü'l-feth) diye anılır?", ["Hicretin 8. yılı", "Hicretin 6. yılı", "Hicretin 10. yılı", "Hicretin 2. yılı"], "Mekke hicretin 8. yılında fethedildi; bu yıl fetih yılı olarak bilinir."),
"sira_186": ("Mekke'nin fethinden kısa süre sonra Hevazin kabilelerine karşı hangi savaş oldu?", ["Huneyn", "Bedir", "Uhud", "Hayber"], "Huneyn fetihten kısa süre sonra Mekke ile Taif arasındaki bir vadide gerçekleşti."),
"sira_187": ("Huneyn'deki sarsıntıdan sonra Allah, Elçisine ﷺ ve müminlere neyi indirdi?", ["Sekînetini ve görmedikleri ordular", "Yağmur", "Bir rüzgâr", "Süvari takviyesi"], "«Sonra Allah, Elçisinin ve müminlerin üzerine sekînetini indirdi ve görmediğiniz ordular indirdi»."),
"sira_188": ("Huneyn'den sonra Müslüman ordu hangi şehre yöneldi?", ["Taif", "Hayber", "Tebük", "Sana"], "Huneyn'den sonra Müslümanlar, halkı kalelere sığınmış olan Taif'i kuşattı."),
"sira_189": ("Kur'an hangi seferi «zorluk saati» (sâatü'l-usre) diye anar?", ["Tebük", "Bedir", "Hayber", "Huneyn"], "«Andolsun Allah, Peygamberin, muhacirlerin ve ensarın tövbesini kabul etti; onlar zorluk saatinde ona uymuşlardı»."),
"sira_190": ("Kur'an, Tebük'te geri kalan üç sahabi hakkında affedilmeden önce ne der?", ["Bütün genişliğine rağmen yeryüzü onlara dar geldi, sonra Allah tövbelerini kabul etti", "Sürgün edildiler", "Yemen'e gittiler", "Unutuldular"], "«Geri bırakılan üç kişinin de tövbesini kabul etti: yeryüzü bütün genişliğine rağmen onlara dar gelmişti… sonra tövbelerini kabul etti»."),
"sira_191": ("Son büyük seferin hedefi Tebük hangi yöndedir?", ["Kuzeyde, Şam sınırına doğru", "Güneyde, Yemen'e doğru", "Doğuda, Irak'a doğru", "Batıda, Kızıldeniz'de"], "Tebük Medine'nin kuzeyinde, Şam yolu üzerindedir; Peygamberin ﷺ son büyük seferiydi."),
"sira_192": ("Hangi sahabi Tebük ordusunun büyük bir kısmını kendi malıyla donattı?", ["Osman b. Affan", "Sa'd b. Ebi Vakkas", "Talha b. Ubeydullah", "Ebu Zer"], "Osman b. Affan «zorluk ordusunun» (ceyşü'l-usre) donanımının önemli bir bölümünü karşıladı."),
"sira_193": ("Allah yolunda ilk oku hangi sahabi attı?", ["Sa'd b. Ebi Vakkas", "Zübeyr b. Avvam", "Talha b. Ubeydullah", "Ebu Ubeyde"], "İlk Müslümanlardan Sa'd b. Ebi Vakkas, Allah yolunda ilk ok atan kişi olarak bilinir."),
"sira_194": ("Hangi sahabiye «Allah Resulünün ﷺ havarisi» denir?", ["Zübeyr b. Avvam", "Ebu Hureyre", "Selman-ı Farisi", "Bilal"], "Peygamberin ﷺ halasının oğlu Zübeyr b. Avvam onun havarisi, yakın destekçisi olarak anıldı."),
"sira_195": ("Münafıkların bilgisi hangi sahabiye emanet edildi ve bu yüzden «sır sahibi» diye anıldı?", ["Huzeyfe b. Yeman", "Ebu Musa el-Eş'ari", "Ammar b. Yasir", "Ebu'd-Derda"], "Huzeyfe b. Yeman «sâhibü's-sır» diye bilinir; Peygamber ﷺ münafıklar hakkında bildiğini ona söylemişti."),
"sira_196": ("Hendek fikrini öneren «Farisi» lakaplı Selman hangi diyardandı?", ["İran'dan", "Yemen'den", "Habeşistan'dan", "Bizans'tan"], "Fars asıllı Selman, Medine'de Peygambere ﷺ katılmadan önce uzun süre hakikati aradı."),
"sira_197": ("Enes b. Malik'in annesi olan hangi hanım oğlunun hizmetini Peygambere ﷺ sundu?", ["Ümmü Süleym", "Ümmü Seleme", "Ümmü Eymen", "Ümmü Habibe"], "Ensardan Ümmü Süleym, Peygamber ﷺ Medine'ye geldiğinde oğlu Enes'i ona hizmet etmesi için takdim etti."),
"sira_198": ("Peygamberin ﷺ hangi eşi geniş ilmiyle tanınır ve çok hadis rivayet etmiştir?", ["Aişe", "Sevde", "Cüveyriye", "Meymune"], "Ebu Bekir'in kızı Aişe, en çok hadis rivayet edenlerden ve dinî ilimlerde bir mercidir."),
"sira_199": ("Peygamberin ﷺ hangi eşi halasının kızıydı ve evliliği Ahzab suresinde anılır?", ["Zeyneb bint Cahş", "Hafsa", "Ümmü Seleme", "Safiyye"], "Zeyneb bint Cahş ile evlilik Ahzab suresinde (33:37) zikredilir."),
"sira_200": ("Peygamberin ﷺ hangi eşi Hudeybiye'deki tıkanıklığı çözen tavsiyede bulundu?", ["Ümmü Seleme", "Aişe", "Hafsa", "Zeyneb bint Cahş"], "Ümmü Seleme Peygambere ﷺ çıkıp kendisinin kurbanı kesip tıraş olmasını tavsiye etti; sahabiler hemen ona uydu."),
"sira_201": ("Peygamberin ﷺ dedesine kadar tam adı nedir?", ["Muhammed b. Abdullah b. Abdülmuttalib", "Muhammed b. Ebi Talib", "Muhammed b. Abbas", "Muhammed b. Haşim"], "O, Kureyş kabilesinden Abdülmuttalib oğlu Abdullah oğlu Muhammed'dir."),
"sira_202": ("Kur'an'da İsa tarafından anılan ve «en çok övülen» anlamına gelen diğer adı nedir?", ["Ahmed", "Mustafa", "Emin", "Ebu'l-Kasım"], "İsa kendisinden sonra gelecek «adı Ahmed olan» bir elçiyi müjdeledi (Kur'an 61:6)."),
"sira_203": ("Kur'an'ın Peygambere ﷺ inişi ne kadar sürdü?", ["Yaklaşık yirmi üç yıl", "On yıl", "Kırk yıl", "Tek bir gece"], "Vahiy yaklaşık yirmi üç yıl sürdü: on üç yıl Mekke'de, on yıl Medine'de."),
"sira_204": ("İslam'ı kabul eden ilk hür yetişkin erkek hangi sahabidir?", ["Ebu Bekir es-Sıddîk", "Ömer b. Hattab", "Osman b. Affan", "Sa'd b. Ebi Vakkas"], "Hür ve yetişkin erkekler arasında Peygamberin ﷺ davetine ilk uyan Ebu Bekir'dir."),
"sira_205": ("İslam'ı kabul eden ilk çocuk kimdir?", ["Ali b. Ebi Talib", "Enes b. Malik", "Üsame b. Zeyd", "Abdullah b. Ömer"], "Peygamberin ﷺ evinde yetişen Ali b. Ebi Talib, iman eden ilk çocuktur."),
"sira_206": ("Peygamberin ﷺ azatlılarından ilk Müslüman olan kimdir?", ["Zeyd b. Harise", "Bilal b. Rebah", "Suheyb er-Rumi", "Selman-ı Farisi"], "Peygamberin ﷺ azat edip evlat gibi büyüttüğü Zeyd b. Harise, azatlılardan ilk iman edendir."),
"sira_207": ("Peygamberin ﷺ onların erkeklerinden hiçbirinin babası olmadığını bildirerek evlat edinmeye son veren ayet hangisidir?", ["«Muhammed sizin erkeklerinizden hiçbirinin babası değildir; o Allah'ın elçisi ve peygamberlerin sonuncusudur»", "«Onları babalarına nispet edin»", "«Kan bağı önceliklidir»", "«Evlat edinmeyin»"], "«Muhammed sizin erkeklerinizden hiçbirinin babası değildir; fakat o Allah'ın elçisi ve peygamberlerin sonuncusudur»."),
"sira_208": ("Medine'de başlatılan cemaat namazı için Müslümanlar haftanın hangi günü toplanır?", ["Cuma", "Cumartesi", "Pazar", "Pazartesi"], "Cuma namazı Medine'de başlatıldı ve her hafta cemaati bir araya getirir."),
"sira_209": ("Peygamberin ﷺ son hastalığında onun emriyle namazı hangi sahabi kıldırdı?", ["Ebu Bekir es-Sıddîk", "Ömer b. Hattab", "Ali b. Ebi Talib", "Bilal"], "Peygamber ﷺ hastalığında Ebu Bekir'in namazı kıldırmasını emretti; sahabiler bunu bir işaret saydı."),
"sira_210": ("Hangi halife sabah namazını kıldırırken şehit edildi?", ["Ömer b. Hattab", "Ebu Bekir", "Ali b. Ebi Talib", "Muaviye"], "Ömer b. Hattab Medine'de sabah namazında yaralandı ve aldığı yaralardan vefat etti."),
"sira_211": ("Ebu Bekir'in halifeliği ne kadar sürdü?", ["Yaklaşık iki yıl", "On yıl", "Yirmi yıl", "Otuz yıl"], "Ebu Bekir vefatına kadar yaklaşık iki yıl hüküm sürdü; yerine Ömer geçti."),
"sira_212": ("Ebu Bekir halifeliğinin başında hangi harekete karşı hareket etmek zorunda kaldı?", ["Zekâtı reddeden ve dinden dönen bazı kabilelere", "İran'dan gelen bir istilaya", "Bir kıtlığa", "Medine'de bir isyana"], "İlk halifelik, zekâtı reddeden veya İslam'dan dönen kabilelere karşı ridde savaşlarıyla başladı."),
"sira_213": ("Ömer b. Hattab ümmetin başı olarak hangi unvanı aldı?", ["Emîrü'l-müminîn", "Sultan", "Melik", "İmamü'l-Haremeyn"], "Emîrü'l-müminîn unvanı Ömer döneminde yerleşti ve sonraki halifeler tarafından taşındı."),
"sira_214": ("Kudüs'teki hangi mescit Müslümanların ilk kıblesiydi?", ["Mescid-i Aksa", "Kuba Mescidi", "Peygamber ﷺ Mescidi", "Mescid-i Haram"], "Müslümanlar kıble Kâbe'ye çevrilmeden önce Kudüs'e yönelerek namaz kıldılar."),
"sira_215": ("Yolculuk yapılması özellikle teşvik edilen üç mescit hangileridir?", ["Mescid-i Haram, Peygamber ﷺ Mescidi ve Mescid-i Aksa", "Kuba, Aksa ve Kûfe", "Mescid-i Haram, Kuba ve Şam", "Aksa, Kûfe ve Basra"], "Üç mescide yolculuk özellikle teşvik edilir: Mescid-i Haram, Peygamber ﷺ Mescidi ve Mescid-i Aksa."),
"sira_216": ("Peygamber ﷺ Arefe günü Veda Hutbesi'ni nerede irat etti?", ["Arafat'ta Urane vadisinde", "Mina'da", "Kâbe önünde", "Müzdelife'de"], "Veda Hutbesi Arefe günü Arafat eteğindeki Urane vadisinde irat edildi."),
"sira_217": ("Peygamber ﷺ Veda Hutbesi'nde neyi dokunulmaz ilan etti?", ["Herkesin kanını, malını ve namusunu", "Ticaret yollarını", "Medine kuyularını", "Hurma bahçelerini"], "Müslümanların kanlarını, mallarını ve namuslarını, o günün, o ayın ve o beldenin haram oluşu gibi haram ilan etti."),
"sira_218": ("Veda Hutbesi'ne göre Peygamber ﷺ ümmetine sapmamaları için neyi bıraktı?", ["Allah'ın Kitabını", "Bir hazineyi", "Bir orduyu", "Bir haritayı"], "Onlara, sapmamaları için sarılacakları şeyi aralarında bıraktığını hatırlattı: Allah'ın Kitabı."),
"sira_219": ("Peygamberin ﷺ veda haccını yaptığı hac, hicri takvimin hangi ayında yapılır?", ["Zilhicce", "Ramazan", "Muharrem", "Recep"], "Veda haccı hicretin 10. yılı Zilhicce ayında yapıldı."),
"sira_220": ("Peygamberin ﷺ vefatından sonra bedenini kim yıkayıp kefenledi?", ["Ehl-i beytinden kimseler, aralarında Ali ve Abbas", "Sadece ensar", "Bilal ve Enes", "Kuba halkı"], "Bunu kendi ailesi üstlendi; aralarında Ali b. Ebi Talib ve amcası Abbas vardı."),
"sira_221": ("Peygamber ﷺ hicri yılın hangi ayında vefat etti?", ["Rebiülevvel", "Ramazan", "Şevval", "Zilkade"], "Peygamber ﷺ hicretin 11. yılı Rebiülevvel ayında Medine'de vefat etti."),
"sira_222": ("Ebu Bekir, Peygamberin ﷺ ölümlü olduğunu hatırlatmak için hangi ayeti okudu?", ["«Muhammed ancak bir elçidir; ondan önce de elçiler gelip geçmiştir»", "«Seni ancak rahmet olarak gönderdik»", "«Sen büyük bir ahlak üzeresin»", "«Allah'ın yardımı gelince»"], "«Muhammed ancak bir elçidir; ondan önce de elçiler gelip geçmiştir. Şimdi o ölür ya da öldürülürse gerisin geriye mi döneceksiniz?»"),
"sira_223": ("Hangi sahabi ezberlediği hadislerin çokluğuyla tanınır?", ["Ebu Hureyre", "Enes b. Malik", "Cabir b. Abdullah", "Ebu Said el-Hudri"], "Ebu Hureyre Peygamberin ﷺ son yıllarını onun yanında geçirdi ve en çok hadis rivayet eden sahabi oldu."),
"sira_224": ("Peygamberin ﷺ amcasının oğlu olan hangi sahabi tefsirde büyük otorite oldu?", ["Abdullah b. Abbas", "Abdullah b. Ömer", "Abdullah b. Mesud", "Abdullah b. Zübeyr"], "Peygamberin ﷺ kendisi için Kitabı anlamayı dilediği Abdullah b. Abbas «Kur'an'ın tercümanı» diye anıldı."),
"sira_225": ("Peygamber ﷺ hangi sahabiyi Yemen'e vali ve kadı olarak gönderdi; o da genç yaşta Şam'da vefat etti?", ["Muaz b. Cebel", "Ebu Ubeyde b. Cerrah", "Amr b. As", "Halid b. Velid"], "Sahabenin âlimlerinden Muaz b. Cebel Yemen'e gönderildi, sonra genç yaşta Şam'da vefat etti."),
"sira_226": ("Hacda yürünen Safa ile Merve tepeleri arasında hangi vadi uzanır?", ["Kâbe çevresindeki Mekke vadisi", "Urane vadisi", "Mina vadisi", "Bedir vadisi"], "Safa ve Merve, bugün Mescid-i Haram'ın içinde kalan Mekke vadisindeki iki küçük tepedir."),
"sira_227": ("Peygamberin ﷺ gelişinden önce Medine'nin hangi iki büyük Arap kabilesi savaşıyordu?", ["Evs ve Hazrec", "Kureyş ve Hevazin", "Sakif ve Kinane", "Temim ve Bekir"], "Uzun süre düşman olan Evs ve Hazrec, Peygamberin ﷺ gelişinden sonra birlikte ensarı oluşturdu."),
"sira_228": ("Hangi ayet ensara düşman olduklarını ve Allah'ın kalplerini kaynaştırdığını hatırlatır?", ["«Siz düşmandınız, O kalplerinizi kaynaştırdı»", "«Fakirdiniz»", "«Azdınız»", "«Şaşkındınız»"], "«Allah'ın üzerinizdeki nimetini hatırlayın: hani siz düşmandınız da O kalplerinizi kaynaştırdı ve nimetiyle kardeşler oldunuz»."),
"sira_229": ("Kur'an, muhacirleri ağırlamalarında ensarı nasıl över?", ["Kendileri ihtiyaç içinde olsalar bile başkalarını kendilerine tercih ederler", "Onlara arazi sattılar", "Onlara borç verdiler", "Onları şehir dışında barındırdılar"], "«Kendileri ihtiyaç içinde olsalar bile onları kendilerine tercih ederler. Kim nefsinin cimriliğinden korunursa, işte onlar kurtuluşa erenlerdir»."),
"sira_230": ("Peygamberin ﷺ sözleri, fiilleri ve onaylarının bütününe ne denir?", ["Sünnet", "Kur'an", "Siyer", "Tefsir"], "Sünnet, Peygamberin ﷺ söylediği, yaptığı veya onayladığı şeydir; siyer ise hayatının anlatımıdır."),
"sira_231": ("Sahabe kuşağından sonraki kuşağa ne denir?", ["Tâbiîn", "Ensar", "Muhacirler", "Kurrâ"], "Tâbiîn, Peygamberi ﷺ görmeden sahabiyle karşılaşanlardır."),
"sira_232": ("Bir hadisin ravi zincirine ne denir?", ["İsnad", "Metin", "Tefsir", "Tecvid"], "İsnad rivayet zinciri, metin ise hadisin kendi lafzıdır."),
"sira_233": ("«Sahihayn» diye anılan, en titiz sayılan iki hadis kitabı hangileridir?", ["Sahih-i Buhari ve Sahih-i Müslim", "Ebu Davud ve Tirmizi Sünenleri", "Muvatta ve Müsned", "Nesai ve İbn Mace Sünenleri"], "Sahih-i Buhari ile Sahih-i Müslim birlikte «Sahihayn» diye anılır."),
"sira_234": ("Peygamber ﷺ Mescidi ve kabri hangi şehirdedir?", ["Medine", "Mekke", "Kudüs", "Taif"], "Peygamber ﷺ Mescidi ve kabri, hicret şehri Medine'dedir."),
"sira_235": ("Medine'ye nispet edilen nur sebebiyle hangi lakap verilir?", ["el-Medinetü'l-Münevvere (nurlu şehir)", "Ümmü'l-Kurâ", "Dârü's-Selâm", "el-Medâin"], "Medine'ye Münevvere denir; Mekke'ye ise Mükerreme denir."),
"sira_236": ("Kur'an Mekke'ye «şehirlerin anası» olarak hangi adı verir?", ["Ümmü'l-Kurâ", "el-Medine", "el-Beledü'l-Emin", "Bekke"], "«…şehirlerin anasını (Ümmü'l-Kurâ) ve çevresindekileri uyarasın diye»."),
"sira_237": ("Peygamberin ﷺ ilk eşi Hatice'nin mesleği neydi?", ["Tüccar", "Hekim", "Şair", "Dokumacı"], "Hatice bint Huveylid Mekke'nin saygın bir tüccarıydı; kervanını genç Muhammed'e ﷺ emanet etti."),
"sira_238": ("Peygamber ﷺ yalnız Hatice ile ne kadar evli kaldı?", ["Onun vefatına kadar; sağlığında başka kimseyle evlenmedi", "İki yıl", "Beş yıl", "Hemen başkalarıyla evlendi"], "Peygamber ﷺ Hatice hayattayken başka kadınla evlenmedi; diğer evlilikleri onun vefatından sonradır."),
"sira_239": ("Peygamberi ﷺ Müslüman olmadan koruyan amcasının adı nedir?", ["Ebu Talib", "Hamza", "Abbas", "Ebu Leheb"], "Ali'nin babası Ebu Talib, vefatına kadar yeğenini Kureyş'e karşı korudu."),
"sira_240": ("Peygamberin ﷺ hangi amcası Müslüman olmadan önce Bedir'de esir düştü?", ["Abbas b. Abdülmuttalib", "Ebu Talib", "Hamza", "Zübeyr b. Abdülmuttalib"], "Peygamberin ﷺ amcası ve Abbasilerin atası olan Abbas, Bedir'de esir alındı ve sonra Müslüman oldu."),
"sira_241": ("Bedir savaşına katılan sahabilere ne denir?", ["Bedriyyûn (Bedir ehli)", "Ensar", "Muhacirler", "Uhudiyyûn"], "Bedir'de bulunan sahabilere Bedriyyûn denir ve bu fazilet onlara mahsustur."),
"sira_242": ("Kur'an ganimetin hangi payını Allah'a, Elçiye, yakınlara, yetimlere, yoksullara ve yolcuya ayırır?", ["Beşte biri", "Yarısı", "Onda biri", "Üçte biri"], "«Bilin ki ganimet olarak aldığınız şeylerin beşte biri Allah'a, Elçisine, yakınlara, yetimlere, yoksullara ve yolcuya aittir»."),
"sira_243": ("Veda Hutbesi ile birlikte anılan, insanların Allah katındaki eşitliğini temellendiren ayet hangisidir?", ["«Allah katında en üstününüz en çok takva sahibi olanınızdır»", "«İnsanlar tek bir babadandır»", "«Kimse başkasının yükünü taşımaz»", "«Dinde zorlama yoktur»"], "«Ey insanlar! Sizi bir erkekle bir dişiden yarattık… Allah katında en üstününüz en çok takva sahibi olanınızdır»."),
"sira_244": ("Yesrib halkıyla yapılan belirleyici buluşma olan ikinci Akabe biatına kaç kişi katıldı?", ["Yetmişten fazla kişilik bir heyet", "Üç", "On", "Beş yüz"], "İkinci Akabe biatı, Yesrib'den yetmişten fazla erkek ve kadından oluşan bir heyeti bir araya getirdi."),
"sira_245": ("Peygamber ﷺ Akabe biatında Yesrib halkından kaç nakib (sorumlu) seçtirdi?", ["On iki", "Dört", "Yedi", "Yirmi"], "Yesrib heyetinin gruplarını temsil etmek ve biatlarına kefil olmak üzere on iki nakib seçildi."),
"sira_246": ("Medine hicretten sonra hangi adı aldı?", ["Medinetü'n-Nebi, Peygamber ﷺ şehri", "Yesrib", "Sadece Taybe", "el-Kurâ"], "Yesrib, «Peygamber ﷺ şehri» anlamında Medinetü'n-Nebi adını aldı, kısaca el-Medine."),
"sira_247": ("Hangi halife Kur'an'ı resmî nüshalar hâlinde çoğaltıp vilayetlere gönderdi?", ["Osman b. Affan", "Ebu Bekir", "Ömer", "Ali"], "Ebu Bekir metni topladı; Osman resmî nüshalar yazdırıp büyük şehirlere gönderdi."),
"sira_248": ("Kur'an Peygambere ﷺ hangi dille indirildi?", ["Arapça", "Aramice", "Farsça", "Yunanca"], "Kur'an, Peygamberin ﷺ kendi kavminin dili olan apaçık Arapça ile indirildi."),
"sira_249": ("Peygamber ﷺ hangi sahabiyi Bahreyn'e gönderdi ve o oranın malıyla döndü?", ["Ebu Ubeyde b. Cerrah", "Bilal", "Enes b. Malik", "Ebu Zer"], "«Bu ümmetin emini» diye anılan Ebu Ubeyde b. Cerrah, Bahreyn'den malla döndü."),
"sira_250": ("Hicri takvimin başlangıcını hangi olay belirler?", ["Mekke'den Medine'ye hicret", "Peygamberin ﷺ doğumu", "İlk vahiy", "Mekke'nin fethi"], "Hicri takvim hicret yılıyla başlar; bu karar Ömer'in halifeliği döneminde alındı."),
}
